 export function liveBeeRunDeps(args: {
   sql: postgres.Sql;
   workspaceId: string;
   harness: string;
   parentSpawnId?: string | null;
   planSlug?: string | null;
+  /** Per-spawn hard kill timeout (ms) threaded to spawnInvokeOnce (EI-172). Null → runner env default. */
