1	/**
2	 * The green-checkpoint job — plan release-gate-ready-branch-2026-06-04, Phase 1
3	 * (D-003); staging→main model since staging-branch-pipeline-2026-06-06.
4	 * Fast-forwards the green pin (`releaseRef`, now the **`main` branch**) to the
5	 * newest integration commit that is GREEN, so `main` only ever holds known-good,
6	 * tests-passing states — with zero manual curation. git-sync keeps committing
7	 * ALL WIP to the integration branch (`staging`, unchanged); this advances the
8	 * green `main` behind it. The gap between staging HEAD and `main` IS the
9	 * untested buffer. Requires `main` NOT to be checked out in the integration
10	 * tree (it lives on `staging`), so `git branch -f main` is free to move.
11	 *
12	 * Two correctness rules from the plan's Risks:
13	 *   - "Green" is measured in an ISOLATED checkout of the CANDIDATE commit (the
14	 *     dedicated checkpoint worktree), NEVER the churning shared tree — otherwise
15	 *     a peer's in-flight edit pollutes test:affected.
16	 *   - It only ever FAST-FORWARDS the green pin (advanceReady refuses non-FF), and
17	 *     reads a FIXED candidate sha up front, so it can't race git-sync's commits.
18	 *
19	 * Effects are injected (CheckpointDeps) so the orchestration is unit-tested
20	 * without running the (heavy) suite; realCheckpointDeps wires the real ones.
21	 */
22	
23	import { spawn } from 'node:child_process';
24	import { mkdirSync, writeFileSync, readdirSync, statSync, unlinkSync } from 'node:fs';
25	import { homedir } from 'node:os';
26	import * as path from 'node:path';
27	import {
28	  revParse,
29	  refExists,
30	  isAncestor,
31	  advanceReady,
32	  type AdvanceResult,
33	} from './git-ops';
34	import type { ReleaseConfig } from './release-config';
35	
36	export interface CheckpointDeps {
37	  /** (Re)build the isolated checkpoint checkout at `ref` (setup-release-checkout.sh). */
38	  setupTree(ref: string): Promise<void>;
39	  /** Run the "green" suite in `treeDir` against `base`; resolve green=true on pass.
40	   *  `failingTests` is a STABLE signature of what failed (test files / workspaces),
41	   *  extracted from the FULL output — used to dedup the release-fixer dispatch by the
42	   *  failure rather than the candidate sha (P-012). */
43	  runGreen(treeDir: string, base: string | null): Promise<{ green: boolean; summary: string; failingTests?: string[] }>;
44	  /** Fast-forward `ready` to `candidate` (advanceReady). */
45	  advance(candidate: string): Promise<AdvanceResult>;
46	  /** Publish `ready` to origin. */
47	  push(ref: string): Promise<void>;
48	  broadcast(summary: string, body?: string): Promise<void>;
49	  /** release-pipeline-resilience-2026-06-09 P-002: open a durable, human-facing
50	   *  `release-not-green` escalation on red. Transition-only (no-op if one is
51	   *  already open) so the hourly tick doesn't re-open it while the gate stays
52	   *  red. Optional so existing test stubs need not provide it. */
53	  escalate?(summary: string, body: string): Promise<void>;
54	  /** Resolve any open `release-not-green` escalation — the gate recovered. */
55	  clearEscalation?(): Promise<void>;
56	  log(s: string): void;
57	}
58	
59	export interface CheckpointResult {
60	  advanced: boolean;
61	  candidate: string;
62	  from: string | null;
63	  green: boolean | null;
64	  reason: 'up-to-date' | 'not-fast-forward' | 'not-green' | 'advanced' | 'create-failed';
65	  summary?: string;
66	  /** P-012: a stable signature of what failed (test files / workspaces) on the
67	   *  not-green path, so the release-fixer dispatch dedups by FAILURE, not candidate sha. */
68	  failingTests?: string[];
69	}
70	
71	/** The marker the green-checkpoint CLI prints its CheckpointResult JSON behind, so the
72	 *  release-actions routine parses one delimited line instead of brace-slicing the whole
73	 *  stdout (P-008). MUST stay in sync with the literal in release-actions.ts. */
74	export const GREEN_CHECKPOINT_RESULT_MARKER = '__GREEN_CHECKPOINT_RESULT__';
75	
76	/** Extract a stable failure signature from the FULL suite output (NOT the 2000-char
77	 *  tail, which can truncate the markers): vitest `FAIL <file>` lines + the affected
78	 *  runner's `>>> <ws> FAILED` workspace markers. Used for the release-fixer dedup. */
79	export function extractFailingTests(out: string): string[] {
80	  const set = new Set<string>();
81	  for (const m of out.matchAll(/^\s*FAIL\s+(\S+)/gm)) set.add(m[1]);
82	  for (const m of out.matchAll(/>>>\s+(\S+)\s+FAILED\b/g)) set.add(m[1]);
83	  return [...set].sort().slice(0, 50);
84	}
85	
86	/** Host-set, test-affecting NON-`PAPERCUSP_` env vars the gate must strip (P-008).
87	 *  `AGENT_MODELS` (the operator's per-role model map, e.g. `{"worker":"opus"}` in
88	 *  .env.local) leaked into the gate and broke `@papercusp/orchestrator` invoke.test
89	 *  2026-06-09 — green in a clean shell, red only under the routine. The gate measures
90	 *  the COMMITTED defaults; tests that need it set it themselves. */
91	export const HOST_ENV_STRIP = ['AGENT_MODELS'];
92	
93	/**
94	 * Build the GREEN suite's environment — the COMMITTED DEFAULTS, with the host's
95	 * identity stripped — as a fresh env (so realCheckpointDeps.runGreen's env logic,
96	 * which twice held `main` red for hours via leaked env, is unit-testable without
97	 * running the suite). `source` defaults to the live process env.
98	 *
99	 * - Strip ALL `PAPERCUSP_*` (a demo flag leaked from the systemd user-manager env
100	 *   held `main` red for hours 2026-06-06; non-flag host vars — PAPERCUSP_OPERATOR_URL
101	 *   / SPAWN_SU_BEARER — struck again 2026-06-07, failing spawn-chokepoint tests 8/8
102	 *   under the routine while the same sha passed in a login shell) + every
103	 *   {@link HOST_ENV_STRIP} key. The host's identity must never define green.
104	 * - `GREEN_CHECKPOINT=1` — a marker so genuinely load-/live-network-sensitive tests
105	 *   that CANNOT be hermetic (real Hyperswarm/DHT, ports) self-exclude via
106	 *   `describe.skipIf(process.env.GREEN_CHECKPOINT === '1')`; they still run in CI/local.
107	 * - `AFFECTED_BASE=<base>` (when given) so test:affected runs exactly the candidate's delta;
108	 *   any host-leaked AFFECTED_BASE is dropped — the `base` arg is the ONLY source, so a
109	 *   base-null full run is never silently narrowed by an inherited value.
110	 * - `VITEST_MAX_FORKS/THREADS` default to 8 (respecting a pre-set value): the checkpoint
111	 *   shares the box with the live fleet; uncapped workers under that load produce timeout
112	 *   FLAKES that read as "not green" (a 1-of-8881 load-flake held `main` back 2026-06-06).
113	 * - `AFFECTED_RETRY_FAILED` defaults to 1 (respecting a pre-set value): re-run a failed
114	 *   workspace once before calling it red — a real regression fails twice, a flake doesn't.
115	 */
116	export function buildGreenCheckpointEnv(
117	  base: string | null,
118	  source: NodeJS.ProcessEnv = process.env,
119	): NodeJS.ProcessEnv {
120	  const env: NodeJS.ProcessEnv = { ...source };
121	  for (const k of Object.keys(env)) {
122	    if (k.startsWith('PAPERCUSP_') || HOST_ENV_STRIP.includes(k)) delete env[k];
123	  }
124	  env.GREEN_CHECKPOINT = '1';
125	  // AFFECTED_BASE comes ONLY from the `base` argument — never a host-leaked value.
126	  // The gate runs the suite with AFFECTED_BASE set, so a child runGreen(tree, null)
127	  // would otherwise inherit that base and silently NARROW a "full" affected run —
128	  // the host's env defining what green measures, the very leak this builder exists
129	  // to prevent (held `main` red on the candidate-base sha, 2026-06-14).
130	  delete env.AFFECTED_BASE;
131	  if (base) env.AFFECTED_BASE = base;
132	  env.VITEST_MAX_FORKS = env.VITEST_MAX_FORKS ?? '8';
133	  env.VITEST_MAX_THREADS = env.VITEST_MAX_THREADS ?? '8';
134	  env.AFFECTED_RETRY_FAILED = env.AFFECTED_RETRY_FAILED ?? '1';
135	  return env;
136	}
137	
138	/** P-012 failure signature for the release-fixer dedup, folding the SPA-build break in:
139	 *  a green run has none; otherwise the extracted suite failures, plus the sentinel
140	 *  `@papercusp/operator-vite` when the build (not the suite) is what failed — so a broken
141	 *  build holds `main` like any other red and dedups by FAILURE, not the hourly candidate sha. */
142	export function checkpointFailureSignature(
143	  fullOutput: string,
144	  green: boolean,
145	  buildOk: boolean,
146	): string[] {
147	  const failingTests = green ? [] : extractFailingTests(fullOutput);
148	  if (!buildOk && !failingTests.includes('@papercusp/operator-vite')) failingTests.push('@papercusp/operator-vite');
149	  return failingTests;
150	}
151	
152	/** De-noise the suite (+ build) output for the held-gate broadcast/escalation: drop npm's
153	 *  error boilerplate (~10 lines/failed-workspace that repeatedly pushed the real `FAIL`
154	 *  test names out of the tail — cost two diagnosis round-trips 2026-06-06) and keep the
155	 *  last 2000 chars (FAIL lines, timeouts, assertion output, the SPA-build failure tail). */
156	export function summarizeSuiteOutput(fullOutput: string): string {
157	  return fullOutput
158	    .split('\n')
159	    .filter((l) => !/^npm error/.test(l))
160	    .join('\n')
161	    .slice(-2000);
162	}
163	
164	export interface CheckpointOpts {
165	  /** Override the candidate (default: integration-branch HEAD). */
166	  candidate?: string;
167	  /** Don't push `ready` to origin (local-only). */
168	  noPush?: boolean;
169	}
170	
171	export async function runGreenCheckpoint(
172	  cfg: ReleaseConfig,
173	  deps: CheckpointDeps,
174	  opts: CheckpointOpts = {},
175	): Promise<CheckpointResult> {
176	  const candidate = opts.candidate
177	    ? await revParse(cfg.integrationRoot, opts.candidate)
178	    : await revParse(cfg.integrationRoot, cfg.integrationBranch);
179	  const lastReady = (await refExists(cfg.integrationRoot, cfg.releaseRef))
180	    ? await revParse(cfg.integrationRoot, cfg.releaseRef)
181	    : null;
182	
183	  if (candidate === lastReady) {
184	    deps.log(`${cfg.releaseRef} already at integration HEAD ${candidate.slice(0, 8)} — nothing to checkpoint`);
185	    return { advanced: false, candidate, from: lastReady, green: null, reason: 'up-to-date' };
186	  }
187	
188	  // The green pin only ever fast-forwards — refuse a candidate that isn't a descendant.
189	  if (lastReady && !(await isAncestor(cfg.integrationRoot, lastReady, candidate))) {
190	    deps.log(`candidate ${candidate.slice(0, 8)} is NOT a descendant of ${cfg.releaseRef} ${lastReady.slice(0, 8)} — refusing`);
191	    return { advanced: false, candidate, from: lastReady, green: null, reason: 'not-fast-forward' };
192	  }
193	
194	  deps.log(`checkpointing candidate ${candidate.slice(0, 8)} (base ${lastReady?.slice(0, 8) ?? 'none'})`);
195	  await deps.setupTree(candidate);
196	  const { green, summary, failingTests } = await deps.runGreen(cfg.checkpointRoot, lastReady);
197	  if (!green) {
198	    deps.log(`candidate ${candidate.slice(0, 8)} is NOT green — ${cfg.releaseRef} stays at ${lastReady?.slice(0, 8) ?? 'unset'}`);
199	    await deps
200	      .broadcast(
201	        `🟥 green-checkpoint: ${candidate.slice(0, 8)} not green — \`${cfg.releaseRef}\` held at ${lastReady?.slice(0, 8) ?? 'unset'}`,
202	        summary,
203	      )
204	      .catch(() => {});
205	    // release-pipeline-resilience-2026-06-09 P-005: emit a reaction event on the
206	    // RED path, symmetric with the `release:green` emit below. A `release-fixer`
207	    // launch-blueprint (P-006) reacts to this to auto-diagnose the failing test;
208	    // it also unblocks any agent that `events:await`s the gate verdict. The
209	    // `summary` is the de-noised failing-test tail already captured above.
210	    void import('@papercusp/operator-core/lib/events/await/engine')
211	      .then(({ emitAwaitedEvent }) =>
212	        emitAwaitedEvent({
213	          key: 'green-checkpoint:red',
214	          summary: `green-checkpoint: ${candidate.slice(0, 8)} not green — ${cfg.releaseRef} held`,
215	          payload: { sha: candidate, from: lastReady ?? null, summary },
216	          source: 'green-checkpoint',
217	        }),
218	      )
219	      .catch(() => {});
220	    // P-002: durable human-facing escalation (transition-only, cleared on green).
221	    await deps.escalate?.(
222	      `green-checkpoint held: ${candidate.slice(0, 8)} not green`,
223	      `\`${cfg.releaseRef}\` stays at ${lastReady?.slice(0, 8) ?? 'unset'}.\n\nFailing tail:\n${summary}`,
224	    ).catch(() => {});
225	    return { advanced: false, candidate, from: lastReady, green: false, reason: 'not-green', summary, failingTests };
226	  }
227	
228	  const adv = await deps.advance(candidate);
229	  if (adv.advanced && !opts.noPush) {
230	    await deps.push(cfg.releaseRef).catch((e) => deps.log(`warn: push ${cfg.releaseRef} failed: ${e}`));
231	  }
232	  deps.log(`✅ ${cfg.releaseRef} advanced ${adv.from?.slice(0, 8) ?? 'none'} → ${candidate.slice(0, 8)} (green)`);
233	  await deps
234	    .broadcast(
235	      `🟩 green-checkpoint: \`${cfg.releaseRef}\` advanced to ${candidate.slice(0, 8)} (green, deployable)`,
236	      `Was ${adv.from?.slice(0, 8) ?? 'unset'}. The next deploy will pick this up.`,
237	    )
238	    .catch(() => {});
239	  // P-002: the gate recovered — resolve any open `release-not-green` escalation.
240	  await deps.clearEscalation?.().catch(() => {});
241	  // await-event-primitive-2026-06-05 P-015: `release:green` is awaitable —
242	  // an agent blocked on "the next green ready" sleeps on it (events:await)
243	  // instead of polling the checkpoint. Fire-and-forget.
244	  void import('@papercusp/operator-core/lib/events/await/engine')
245	    .then(({ emitAwaitedEvent }) =>
246	      emitAwaitedEvent({
247	        key: 'release:green',
248	        summary: `${cfg.releaseRef} advanced to ${candidate.slice(0, 8)} (green, deployable)`,
249	        payload: { sha: candidate, from: adv.from },
250	        source: 'green-checkpoint',
251	      }),
252	    )
253	    .catch(() => {});
254	  return { advanced: adv.advanced, candidate, from: adv.from, green: true, reason: 'advanced', summary };
255	}
256	
257	/** Real effect wiring. The heavy bit — runGreen — runs the configured suite in
258	 *  the isolated checkpoint tree with AFFECTED_BASE pinned to the last green. */
259	/** The shell-exec seam realCheckpointDeps shells the heavy ops through. Defaults
260	 *  to the module's spawn-backed runCmd; injected as a fake so the real-path
261	 *  WIRING (env-strip, SPA-build-folds-into-green per P-005, the push guard, the
262	 *  setup-script invocation) is unit-testable without running the suite / build /
263	 *  a git push (hive-run-evaluation gap #10). */
264	export type CheckpointExec = (
265	  cmd: string,
266	  args: string[],
267	  opts?: { cwd?: string; env?: NodeJS.ProcessEnv; allowNonZero?: boolean },
268	) => Promise<{ code: number; stdout: string; stderr: string }>;
269	
270	export function realCheckpointDeps(cfg: ReleaseConfig, exec: CheckpointExec = runCmd): CheckpointDeps {
271	  const log = (s: string) => console.log(`[green-checkpoint] ${s}`);
272	  return {
273	    async setupTree(ref) {
274	      const script = path.join(cfg.integrationRoot, 'apps/operator/bin/release/setup-release-checkout.sh');
275	      await exec('bash', [script, '--ref', ref, '--integration', cfg.integrationRoot, '--release', cfg.checkpointRoot, '--node-modules', 'auto']);
276	    },
277	    async runGreen(treeDir, base) {
278	      const [cmd, ...args] = cfg.greenCmd.split(' ');
279	      // The gate measures the COMMITTED DEFAULTS: buildGreenCheckpointEnv strips the
280	      // host's identity (all PAPERCUSP_* + HOST_ENV_STRIP), pins AFFECTED_BASE to the
281	      // last green, caps vitest parallelism + retries once to absorb load-flakes, and
282	      // marks GREEN_CHECKPOINT=1 (its doc records the incidents behind each rule).
283	      const env = buildGreenCheckpointEnv(base);
284	      const r = await exec(cmd, args, { cwd: treeDir, env, allowNonZero: true });
285	
286	      // P-005: the SPA build is PART of "green". A build break (a bad import, a type
287	      // error in a bundled module) passes the Vitest suite, then fails at the deploy's
288	      // swap step (`--build-spa`) and rolls back — needlessly draining + restarting the
289	      // live :3070 (2026-06-09 13:31–14:00: three rolled-back deploys of the same broken
290	      // green). Build it here, in the isolated checkpoint tree, so a broken build holds
291	      // `main` like any other red — before it ever reaches a deploy. Only run it once the
292	      // suite is green (a red suite already holds `main`; no point building).
293	      let buildOut = '';
294	      let buildOk = true;
295	      if (r.code === 0) {
296	        const b = await exec('npm', ['--workspace', '@papercusp/operator-vite', 'run', 'build'], {
297	          cwd: treeDir,
298	          env,
299	          allowNonZero: true,
300	        });
301	        buildOk = b.code === 0;
302	        if (!buildOk) {
303	          buildOut = '\n\n=== SPA BUILD FAILED (@papercusp/operator-vite) — would fail the deploy swap ===\n' + b.stdout + b.stderr;
304	        }
305	      }
306	      const green = r.code === 0 && buildOk;
307	      const fullOutput = r.stdout + r.stderr + buildOut;
308	
309	      // Persist the FULL suite (+ build) output — the 2000-char tail below repeatedly
310	      // proved undiagnosable post-hoc ("2 non-quarantined task(s) failed" with no test
311	      // names survived the truncation; 2026-06-06/07 cost five diagnosis round-trips +
312	      // manual re-runs). One file per run, tiny disk, names every failure forever.
313	      try {
314	        const logDir = path.join(homedir(), '.papercusp', 'checkpoint-logs');
315	        mkdirSync(logDir, { recursive: true });
316	        const stamp = new Date().toISOString().replace(/[:.]/g, '-');
317	        const logPath = path.join(logDir, `${stamp}-base-${(base ?? 'none').slice(0, 12)}.log`);
318	        writeFileSync(logPath, fullOutput);
319	        log(`full suite output → ${logPath}`);
320	        // P-014: prune logs older than 14 days so this dir doesn't grow unbounded.
321	        pruneOldLogs(logDir, 14);
322	      } catch { /* best-effort — the gate verdict must not depend on logging */ }
323	
324	      // P-012: a stable failure signature from the FULL output (before truncation), folding
325	      // the SPA build break in, so the release-fixer dedups by WHAT failed, not the candidate
326	      // sha. The de-noised 2000-char tail rides the held-gate broadcast/escalation.
327	      const failingTests = checkpointFailureSignature(fullOutput, green, buildOk);
328	      const summary = summarizeSuiteOutput(fullOutput);
329	      return { green, summary, failingTests };
330	    },
331	    advance: (candidate) => advanceReady(cfg.integrationRoot, candidate, cfg.releaseRef),
332	    // PAPERCUSP_MAIN_PUSH_OK=1 — green-checkpoint is the ONE writer allowed past
333	    // the pre-push guard on `main` (bin/git-hooks/pre-push). Everyone else's
334	    // pushes to main are blocked by that hook.
335	    push: async (ref) => {
336	      await exec('git', ['-C', cfg.integrationRoot, 'push', 'origin', `${ref}:${ref}`], {
337	        env: { ...process.env, PAPERCUSP_MAIN_PUSH_OK: '1' },
338	      });
339	    },
340	    async broadcast(summary, body) {
341	      const { sendMessage } = await import('@papercusp/operator-core/lib/agent-tools/coordination/messages');
342	      await sendMessage(
343	        { ownerId: 'green-checkpoint', ownerLabel: 'green-checkpoint', source: 'static-client', workspaceId: null, userId: null },
344	        { to: ['*'], summary, body, category: 'service-health' },
345	      );
346	    },
347	    // P-002: durable human-facing escalation surface for a held gate. Tagged
348	    // `source: 'green-checkpoint'` so the open/clear pair is idempotent across
349	    // the hourly tick. Fail-safe — the gate verdict never depends on this.
350	    async escalate(summary, body) {
351	      const { openEscalation, listEscalations } = await import(
352	        '@papercusp/operator-core/lib/agent-tools/coordination/escalations'
353	      );
354	      const open = await listEscalations({ status: 'open' });
355	      if (open.some((e) => (e as Record<string, unknown>).source === 'green-checkpoint')) return;
356	      await openEscalation(
357	        { ownerId: 'green-checkpoint', ownerLabel: 'green-checkpoint', source: 'static-client', workspaceId: null, userId: null },
358	        { severity: 'blocker', summary, body, meta: { source: 'green-checkpoint' } },
359	      );
360	    },
361	    async clearEscalation() {
362	      const { listEscalations, resolveEscalation } = await import(
363	        '@papercusp/operator-core/lib/agent-tools/coordination/escalations'
364	      );
365	      const open = await listEscalations({ status: 'open' });
366	      for (const e of open) {
367	        if ((e as Record<string, unknown>).source === 'green-checkpoint') {
368	          await resolveEscalation({
369	            msg_id: e.msg_id,
370	            choice: 'gate green',
371	            resolver: 'green-checkpoint',
372	          }).catch(() => {});
373	        }
374	      }
375	    },
376	    log,
377	  };
378	}
379	
380	/** P-014: delete checkpoint-log files older than `days` so the dir doesn't grow
381	 *  unbounded (it was trending ~16MB / 43 files in 3 days). Best-effort, never throws. */
382	function pruneOldLogs(dir: string, days: number): void {
383	  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
384	  try {
385	    for (const f of readdirSync(dir)) {
386	      const p = path.join(dir, f);
387	      try {
388	        if (statSync(p).mtimeMs < cutoff) unlinkSync(p);
389	      } catch { /* skip a vanished/locked file */ }
390	    }
391	  } catch { /* dir gone — nothing to prune */ }
392	}
393	
394	function runCmd(
395	  cmd: string,
396	  args: string[],
397	  opts: { cwd?: string; env?: NodeJS.ProcessEnv; allowNonZero?: boolean } = {},
398	): Promise<{ code: number; stdout: string; stderr: string }> {
399	  return new Promise((resolve, reject) => {
400	    const child = spawn(cmd, args, { cwd: opts.cwd, env: opts.env ?? process.env });
401	    let stdout = '';
402	    let stderr = '';
403	    child.stdout.on('data', (d) => (stdout += d.toString()));
404	    child.stderr.on('data', (d) => (stderr += d.toString()));
405	    child.on('error', reject);
406	    child.on('close', (code) => {
407	      if (code === 0 || opts.allowNonZero) resolve({ code: code ?? 0, stdout, stderr });
408	      else reject(new Error(`${cmd} ${args.join(' ')} exited ${code}: ${stderr || stdout}`));
409	    });
410	  });
411	}
412	
413	// CLI: `tsx green-checkpoint.ts [--candidate <ref>] [--no-push]`
414	if (require.main === module) {
415	  const { releaseConfig } = require('./release-config') as typeof import('./release-config');
416	  const cfg = releaseConfig();
417	  const arg = (f: string) => {
418	    const i = process.argv.indexOf(f);
419	    return i >= 0 ? process.argv[i + 1] : undefined;
420	  };
421	  runGreenCheckpoint(cfg, realCheckpointDeps(cfg), {
422	    candidate: arg('--candidate'),
423	    noPush: process.argv.includes('--no-push'),
424	  })
425	    .then((r) => {
426	      // The pretty result goes to STDERR (human-readable); STDOUT carries ONLY the
427	      // single marker line. CRITICAL for cross-version compat: the routine that invokes
428	      // this CLI runs from the integration tree, so a DEPLOYED (older) green-checkpoint
429	      // handler — which still brace-slices stdout `slice(indexOf('{'), lastIndexOf('}'))`
430	      // — runs THIS newer CLI. Two JSON objects on stdout (pretty + marker) made that
431	      // slice span both + the marker text → invalid JSON → recorded 'error' (and wedged
432	      // the pipeline). One object on stdout keeps the old brace-slice AND the new marker
433	      // parse both working.
434	      console.error(JSON.stringify(r, null, 2));
435	      console.log(`${GREEN_CHECKPOINT_RESULT_MARKER} ${JSON.stringify(r)}`);
436	      process.exit(0);
437	    })
438	    .catch((e) => {
439	      console.error('[green-checkpoint] FAILED:', e instanceof Error ? e.message : e);
440	      process.exit(1);
441	    });
442	}
