1	#!/usr/bin/env node
2	// Find workspaces affected by a git diff and run their vitest suites.
3	//
4	// Usage:
5	//   node scripts/affected-tests.mjs [--base <ref>] [--integration] [--all]
6	//
7	// Defaults:
8	//   --base origin/main
9	//   runs the unit suite (`npm test`) per affected workspace
10	//
11	// Flags:
12	//   --integration   also run `npm run test:integration` where defined
13	//   --all           ignore git diff; run every workspace's tests
14	//   --dry           print what would run, don't run
15	
16	import { execSync, spawnSync } from 'node:child_process';
17	import { readFileSync, existsSync } from 'node:fs';
18	import { dirname, join, relative, resolve } from 'node:path';
19	import { fileURLToPath } from 'node:url';
20	
21	const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
22	const args = process.argv.slice(2);
23	const arg = (k, d) => {
24	  const i = args.indexOf(k);
25	  return i >= 0 && args[i + 1] && !args[i + 1].startsWith('--') ? args[i + 1] : d;
26	};
27	const has = (k) => args.includes(k);
28	
29	const base = arg('--base', process.env.AFFECTED_BASE || 'origin/main');
30	const runIntegration = has('--integration');
31	const runAll = has('--all');
32	const dry = has('--dry');
33	const runElSuite = has('--el-suite');
34	const excludeArg = arg('--exclude', '');
35	const excludes = new Set(excludeArg.split(',').filter(Boolean));
36	
37	// Read quarantine.txt: workspace-level entries get added to excludes (logged
38	// as quarantined, not silently skipped). Per-file quarantine is informational
39	// only — vitest doesn't have a per-file skip flag from outside.
40	const quarantineFile = join(ROOT, 'quarantine.txt');
41	const quarantined = new Set();
42	if (existsSync(quarantineFile)) {
43	  for (const raw of readFileSync(quarantineFile, 'utf8').split('\n')) {
44	    const line = raw.replace(/#.*$/, '').trim();
45	    if (!line) continue;
46	    const [ws] = line.split('::');
47	    if (ws) quarantined.add(ws);
48	  }
49	}
50	
51	function sh(cmd) {
52	  return execSync(cmd, { cwd: ROOT, encoding: 'utf8' }).trim();
53	}
54	
55	const root = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'));
56	const workspaces = expandWorkspaces(root.workspaces);
57	
58	function expandWorkspaces(patterns) {
59	  const out = [];
60	  for (const p of patterns) {
61	    if (p.includes('*')) {
62	      const base = p.replace(/\/\*$/, '');
63	      const baseDir = join(ROOT, base);
64	      if (!existsSync(baseDir)) continue;
65	      for (const entry of execSync(`ls -1 ${JSON.stringify(baseDir)}`, { encoding: 'utf8' })
66	        .trim()
67	        .split('\n')
68	        .filter(Boolean)) {
69	        const dir = join(base, entry);
70	        if (existsSync(join(ROOT, dir, 'package.json'))) out.push(dir);
71	      }
72	    } else if (existsSync(join(ROOT, p, 'package.json'))) {
73	      out.push(p);
74	    }
75	  }
76	  return out;
77	}
78	
79	const wsByName = new Map();
80	const wsByDir = new Map();
81	for (const dir of workspaces) {
82	  const pkg = JSON.parse(readFileSync(join(ROOT, dir, 'package.json'), 'utf8'));
83	  const meta = { dir, name: pkg.name, scripts: pkg.scripts || {}, deps: depsOf(pkg) };
84	  wsByName.set(pkg.name, meta);
85	  wsByDir.set(dir, meta);
86	}
87	
88	function depsOf(pkg) {
89	  return new Set(
90	    Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}), ...(pkg.peerDependencies || {}) }),
91	  );
92	}
93	
94	// Reverse-dependency map: which workspaces depend on X?
95	const reverseDeps = new Map();
96	for (const ws of wsByDir.values()) {
97	  for (const dep of ws.deps) {
98	    if (!wsByName.has(dep)) continue;
99	    if (!reverseDeps.has(dep)) reverseDeps.set(dep, new Set());
100	    reverseDeps.get(dep).add(ws.name);
101	  }
102	}
103	
104	function affectedWorkspaces() {
105	  if (runAll) return [...wsByDir.values()];
106	
107	  let changed;
108	  try {
109	    changed = sh(`git diff --name-only ${base}...HEAD`).split('\n').filter(Boolean);
110	    const uncommitted = sh('git diff --name-only HEAD').split('\n').filter(Boolean);
111	    const untracked = sh('git ls-files --others --exclude-standard').split('\n').filter(Boolean);
112	    changed = [...new Set([...changed, ...uncommitted, ...untracked])];
113	  } catch (e) {
114	    console.error(`git diff against ${base} failed: ${e.message}`);
115	    console.error('falling back to --all');
116	    return [...wsByDir.values()];
117	  }
118	
119	  const directlyChanged = new Set();
120	  for (const file of changed) {
121	    for (const ws of wsByDir.values()) {
122	      if (file === `${ws.dir}/package.json` || file.startsWith(`${ws.dir}/`)) {
123	        directlyChanged.add(ws.name);
124	      }
125	    }
126	  }
127	
128	  // Walk reverse-deps transitively
129	  const affected = new Set(directlyChanged);
130	  const queue = [...directlyChanged];
131	  while (queue.length) {
132	    const name = queue.shift();
133	    const dependents = reverseDeps.get(name);
134	    if (!dependents) continue;
135	    for (const d of dependents) {
136	      if (!affected.has(d)) { affected.add(d); queue.push(d); }
137	    }
138	  }
139	
140	  return [...affected].map((name) => wsByName.get(name)).filter(Boolean);
141	}
142	
143	/**
144	 * Detect "EL-relevant" file changes — persona, sync script, the test
145	 * itself, or any registered command def the agent might call. When
146	 * these change AND --integration is set, auto-enable --el-suite so the
147	 * operator's voice agent doesn't drift unnoticed.
148	 */
149	function elSuiteAutoTrigger() {
150	  if (runAll) return false; // user already opted into everything
151	  let changed;
152	  try {
153	    changed = sh(`git diff --name-only ${base}...HEAD`).split('\n').filter(Boolean);
154	    const uncommitted = sh('git diff --name-only HEAD').split('\n').filter(Boolean);
155	    const untracked = sh('git ls-files --others --exclude-standard').split('\n').filter(Boolean);
156	    changed = [...new Set([...changed, ...uncommitted, ...untracked])];
157	  } catch { return false; }
158	  return changed.some((f) =>
159	    f === 'apps/operator/prompts/operator.persona.md' ||
160	    f === 'apps/operator/scripts/el-agent-sync.mjs' ||
161	    f === 'apps/operator/scripts/el-suite-test.mjs' ||
162	    f.startsWith('apps/operator/lib/commands/defs/')
163	  );
164	}
165	if (runIntegration && !runElSuite && elSuiteAutoTrigger()) {
166	  console.log('(EL-relevant files changed — auto-enabling --el-suite)');
167	  // mutate the flag so the task collector below picks it up
168	  // eslint-disable-next-line no-global-assign
169	  globalThis.__autoElSuite = true;
170	}
171	
172	const affected = affectedWorkspaces();
173	
174	if (!affected.length) {
175	  console.log('No affected workspaces.');
176	  process.exit(0);
177	}
178	
179	const tasks = [];
180	for (const ws of affected) {
181	  if (excludes.has(ws.name)) { console.log(`(excluded ${ws.name})`); continue; }
182	  if (ws.scripts.test) tasks.push({ ws, script: 'test' });
183	  // Static drift check between el-agent-sync TOOLS list and the
184	  // commands registry. Cheap (no network), catches the runtime crash
185	  // class that hit us yesterday ("Client tool not defined on client").
186	  // Always runs when present — no integration flag gate.
187	  if (ws.scripts['lint:el-tools']) tasks.push({ ws, script: 'lint:el-tools' });
188	  if (runIntegration && ws.scripts['test:integration']) tasks.push({ ws, script: 'test:integration' });
189	  // EL Conv AI behavior suite. Hits the live agent; expensive (a few
190	  // EL minutes per run). Gated behind --integration AND --el-suite
191	  // because most operator changes don't affect persona/tools — opt-in
192	  // when you've touched prompts/operator.persona.md, scripts/el-agent-
193	  // sync.mjs, lib/commands/defs/**, or want to verify before a release.
194	  // Skips with exit 0 when EL credentials aren't available so CI
195	  // without an XI_API_KEY doesn't fail the gate.
196	  if (runIntegration && (runElSuite || globalThis.__autoElSuite) && ws.scripts['test:el-suite']) tasks.push({ ws, script: 'test:el-suite' });
197	}
198	
199	if (!tasks.length) {
200	  console.log(`Affected: ${affected.map((w) => w.name).join(', ')} — but none declare a 'test' script.`);
201	  process.exit(0);
202	}
203	
204	console.log(`Affected workspaces (${affected.length}): ${affected.map((w) => w.name).join(', ')}`);
205	console.log(`Running ${tasks.length} task(s):`);
206	for (const t of tasks) console.log(`  - ${t.ws.name} :: ${t.script}`);
207	
208	if (dry) process.exit(0);
209	
210	// AFFECTED_RETRY_FAILED=1 (the green-checkpoint sets it): re-run a FAILED
211	// workspace once before counting it. On the shared dev box the gate runs
212	// while the fleet is at load 70-95, and single-test timeout flakes were
213	// holding green `main` back for HOURS (2026-06-06 afternoon: consecutive
214	// not-greens whose identification re-run passed 8867/8867). A real
215	// regression fails both runs; a load flake almost never fails twice in a
216	// row. Default OFF so interactive `test:affected` keeps fail-fast feedback.
217	const retryFailed = process.env.AFFECTED_RETRY_FAILED === '1';
218	
219	// HARDEN-GATE (su-85e11 proposal, landed via brief 09 2026-06-10): when a
220	// workspace fails under AFFECTED_RETRY_FAILED, prefer re-running just the
221	// FAILED FILES in a FRESH process over re-running the whole workspace.
222	// Two flake classes the workspace-level retry handles poorly:
223	//   - cross-file state poisoning (vitest-fail-on-console catching another
224	//     file's late console output; shared bootstrap-graph state) — a fresh
225	//     process clears it where an identical full re-run can reproduce it;
226	//   - peer mid-edit transform errors on the shared tree — scoping the retry
227	//     to the failed files keeps the second run cheap (seconds, not a 10k-test
228	//     suite), so the gate's wall-clock stays bounded under load.
229	// Parse the vitest summary for failed files; when nothing parses (e.g. a
230	// non-vitest failure mode) fall back to the original full-workspace retry.
231	function parseFailedFiles(out) {
232	  const files = new Set();
233	  // ` ❯ lib/x/y.test.ts (22 tests | 1 failed) 85ms` — failed-file summary rows
234	  for (const m of out.matchAll(/^\s*❯\s+(\S+\.(?:test|spec)\.[cm]?[jt]sx?)\s+\([^)]*\bfailed\b[^)]*\)/gm)) {
235	    files.add(m[1]);
236	  }
237	  // `FAIL  lib/x/y.test.ts …` — failed-suite rows (transform/setup errors)
238	  for (const m of out.matchAll(/^\s*FAIL\s+(\S+\.(?:test|spec)\.[cm]?[jt]sx?)\b/gm)) {
239	    files.add(m[1]);
240	  }
241	  return [...files];
242	}
243	const FRESH_RETRY_MAX_FILES = 15; // a broader red is a real regression, not a flake
244	
245	let failed = 0;
246	let quarantinedFailed = 0;
247	for (const t of tasks) {
248	  const isQuarantined = quarantined.has(t.ws.name);
249	  console.log(`\n>>> ${t.ws.name} :: npm run ${t.script}${isQuarantined ? ' [QUARANTINED]' : ''}`);
250	  // Under retryFailed we must capture output to learn WHICH files failed; the
251	  // interactive path keeps stdio:'inherit' for live streaming.
252	  const run = (extraArgs = []) => {
253	    const argv = ['run', t.script, '--workspace', t.ws.dir, ...(extraArgs.length ? ['--', ...extraArgs] : [])];
254	    if (!retryFailed) return spawnSync('npm', argv, { cwd: ROOT, stdio: 'inherit' });
255	    // A full vitest suite emits far beyond spawnSync's 1MB default maxBuffer —
256	    // an ENOBUFS-killed child would read as a failure. 256MB clears any suite.
257	    const r = spawnSync('npm', argv, { cwd: ROOT, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 });
258	    if (r.error) console.error(`>>> ${t.ws.name} spawn error: ${r.error.message}`);
259	    process.stdout.write(r.stdout ?? '');
260	    process.stderr.write(r.stderr ?? '');
261	    return r;
262	  };
263	  let r = run();
264	  if (r.status !== 0 && retryFailed && !isQuarantined) {
265	    const failedFiles = parseFailedFiles(`${r.stdout ?? ''}${r.stderr ?? ''}`);
266	    if (failedFiles.length > 0 && failedFiles.length <= FRESH_RETRY_MAX_FILES) {
267	      console.warn(
268	        `\n>>> ${t.ws.name} FAILED — fresh-process re-run of ${failedFiles.length} failed file(s) (HARDEN-GATE flake absorption): ${failedFiles.join(', ')}`,
269	      );
270	      r = run(failedFiles);
271	      if (r.status === 0)
272	        console.warn(`>>> ${t.ws.name} failed files passed in a fresh process — counted as a FLAKE, not a failure.`);
273	    } else {
274	      console.warn(`\n>>> ${t.ws.name} FAILED — retrying once (AFFECTED_RETRY_FAILED, flake absorption)`);
275	      r = run();
276	      if (r.status === 0) console.warn(`>>> ${t.ws.name} passed on retry — counted as a FLAKE, not a failure.`);
277	    }
278	  }
279	  if (r.status !== 0) {
280	    if (isQuarantined) {
281	      quarantinedFailed++;
282	      console.warn(`  (quarantined failure — not gating)`);
283	    } else {
284	      failed++;
285	    }
286	  }
287	}
288	
289	if (quarantinedFailed) {
290	  console.warn(`\n${quarantinedFailed} quarantined task(s) failed (not gating).`);
291	}
292	if (failed) {
293	  console.error(`\n${failed} non-quarantined task(s) failed.`);
294	  process.exit(1);
295	}
296	console.log('\nAll affected tests passed.');
297

